DECLARE
  l_failures PLS_INTEGER := 0;

  PROCEDURE check_result(
    p_label    VARCHAR2,
    p_actual   NUMBER,
    p_expected NUMBER
  ) IS
  BEGIN
    IF (p_actual IS NULL AND p_expected IS NULL) OR
       (p_actual IS NOT NULL AND p_expected IS NOT NULL AND p_actual = p_expected) THEN
      DBMS_OUTPUT.PUT_LINE(
        'PASS: ' || p_label ||
        ' expected=' || COALESCE(TO_CHAR(p_expected), 'NULL') ||
