      l_failures := l_failures + 1;
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: ' || p_label ||
        ' expected=' || COALESCE(TO_CHAR(p_expected), 'NULL') ||
        ' actual=' || COALESCE(TO_CHAR(p_actual), 'NULL')
      );
    END IF;
  END check_result;
BEGIN
  SAVEPOINT clamp_nonnegative_test;

  check_result(
    p_label    => 'NULL input',
    p_actual   => HARNESS_APP.clamp_nonnegative(NULL),
    p_expected => NULL
  );

  check_result(
    p_label    => 'Negative input -7',
    p_actual   => HARNESS_APP.clamp_nonnegative(-7),
    p_expected => 0
  );

  check_result(
    p_label    => 'Zero input 0',
    p_actual   => HARNESS_APP.clamp_nonnegative(0),
    p_expected => 0
  );

  check_result(
    p_label    => 'Positive input 42',
    p_actual   => HARNESS_APP.clamp_nonnegative(42),
    p_expected => 42
  );

  DBMS_OUTPUT.PUT_LINE('SUMMARY: failures=' || l_failures);

  ROLLBACK TO clamp_nonnegative_test;

  IF l_failures > 0 THEN
    RAISE_APPLICATION_ERROR(
      -20001,
      'clamp_nonnegative test failed: ' || l_failures || ' check(s) failed'
    );
  END IF;
EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('ERROR: ' || SQLERRM);
    ROLLBACK TO clamp_nonnegative_test;
    RAISE;
END;
